/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import type { Sim } from "scenerystack/sim";
import { Tandem } from "scenerystack/tandem";
import { SelectedElementModel } from "../../src/common/model/SelectedElementModel.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import PeriodicTrendsColors from "../../src/PeriodicTrendsColors.js";
import { PeriodicTrendsPreferencesModel } from "../../src/preferences/PeriodicTrendsPreferencesModel.js";
import { ShieldingScreen } from "../../src/shielding/ShieldingScreen.js";
import { TrendsScreen } from "../../src/trends/TrendsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from periodicTrendsQueryParameters.
  const simPreferences = new PeriodicTrendsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // One element shared by both screens: what Trends selects, Shielding explains.
  const selectedElement = new SelectedElementModel(simPreferences.tableExtentProperty);

  const shieldingScreen = new ShieldingScreen({
    selectedElement,
    name: stringManager.getScreenNames().shieldingStringProperty,
    tandem: Tandem.ROOT.createTandem("shieldingScreen"),
    backgroundColorProperty: PeriodicTrendsColors.backgroundColorProperty,
  });

  // Assigned below; the Trends "Explain with shielding" button needs the Sim to switch screens.
  const sim = null as Sim | null;

  const screens = [
    new TrendsScreen({
      selectedElement,
      electronVoltsProperty: simPreferences.electronVoltsProperty,
      showShielding: () => {
        if (sim) {
          sim.selectedScreenProperty.value = shieldingScreen;
        }
      },
      name: stringManager.getScreenNames().trendsStringProperty,
      tandem: Tandem.ROOT.createTandem("trendsScreen"),
      backgroundColorProperty: PeriodicTrendsColors.backgroundColorProperty,
    }),
    shieldingScreen,
  ];

  return {
    screens,
    tracked: { PeriodicTrendsColors, stringManager, simPreferences, selectedElement, shieldingScreen },
  };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
